const body = $input.first().json.body || {};
const kontext = body.context || {};
const postId = String(body.post_id || '');
if (!/^[a-z0-9]{26}$/.test(postId)) {
  throw new Error('Ungueltige post_id');
}
if (kontext.aktion !== 'ticket' || !/^[a-f0-9]{32}$/.test(String(kontext.nonce || ''))) {
  throw new Error('Unbekannte Aktion');
}
return [{ json: { post_id: postId, nonce: kontext.nonce, user_name: String(body.user_name || 'unbekannt') } }];

const eingabe = $('Eingabe pruefen').first().json;
const post = $('Post laden').first().json;
const ich = $input.first().json;
const props = post.props || {};
if (!ich.id || post.user_id !== ich.id) {
  throw new Error('Post stammt nicht vom Bot');
}
if (!props.aktion_nonce || props.aktion_nonce !== eingabe.nonce) {
  throw new Error('Aktion nicht mehr gueltig');
}
return [{ json: { titel: props.aktion_titel || 'Alert aus Mattermost', text: props.aktion_text || '', message: post.message, user: eingabe.user_name } }];

const daten = $('Nonce pruefen').first().json;
const ticket = $input.first().json;
const url = 'https://support-tech.pkr-lab.de/#ticket/zoom/' + ticket.id;
return [{
  json: {
    update: {
      message: daten.message,
      props: {
        aktion_nonce: '',
        attachments: [{ fallback: 'Ticket angelegt', color: '#2e7d32', text: '\u{1F3AB} Ticket #' + ticket.number + ' von @' + daten.user + ' angelegt: ' + url }],
      },
    },
    ephemeral_text: 'Ticket #' + ticket.number + ' angelegt.',
  },
}];
